# CORRECT: grid is dynamic, matches autotuned XBLOCK
@triton.autotune(configs=[Config({'XBLOCK': 512}, num_warps=8), ...], key=['xnumel'])
@triton.jit
def kernel(ptr, xnumel, XBLOCK: tl.constexpr):
    xoffset = tl.program_id(0) * XBLOCK
    xindex = xoffset + tl.arange(0, XBLOCK)
    # ... compute ...

# Grid is a lambda that reads the autotuned XBLOCK from meta
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](ptr, xnumel)

